// lib/central.mjs — a central de esperas do sistema (operações lentas).

// Devolve uma Promise que resolve depois de `ms` milissegundos.
// O event loop cuida do tempo enquanto o programa segue trabalhando.
export function aguardar(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

// Confere o nome com callbacks: aoSucesso recebe o nome limpo (sem espaços
// nas pontas) depois de 2ms; aoErro recebe um erro de 'nome vazio'.
export function conferirNome(nome, aoSucesso, aoErro) {
  if (typeof nome !== 'string' || nome.trim() === '') {
    aoErro(new Error('nome vazio'));
    return;
  }
  setTimeout(() => aoSucesso(nome.trim()), 2);
}

