// lib/fila.mjs — a fila de atendimento da clínica.
import { aguardar, conferirNome } from './central.mjs';

// Devolve o PRIMEIRO da fila e o TIRA da lista (o próximo a ser chamado).
export function proximoDaFila(fila) {
  if (!Array.isArray(fila)) throw new Error('fila inválida');
  if (fila.length === 0) throw new Error('fila vazia');
  return fila.shift();
}

// Devolve a senha no formato do painel: 'S' + número com 3 casas.
export function montarSenha(numero) {
  return 'S' + String(numero).padStart(3, '0');
}

// Emite a senha de um paciente novo (promise): confere o nome com o callback
// conferirNome, espera 1ms com aguardar e resolve com { senha, nome }.
export function emitirSenha(nome, numero) {
  return new Promise((resolve, reject) => {
    conferirNome(
      nome,
      (nomeLimpo) => {
        aguardar(1).then(() => resolve({ senha: montarSenha(numero), nome: nomeLimpo }));
      },
      reject,
    );
  });
}

// Atende o PRÓXIMO da fila (async/await): espera a "ligação do painel" (2ms)
// e devolve o paciente atendido. Fila vazia → a Promise rejeita.
export async function atenderProximo(fila) {
  await aguardar(2);
  return proximoDaFila(fila);
}

