import { test } from 'node:test';
import assert from 'node:assert/strict';
import { aguardar, conferirNome } from './lib/central.mjs';
import { proximoDaFila, montarSenha, emitirSenha, atenderProximo } from './lib/fila.mjs';

test('aguardar devolve uma Promise que espera o tempo pedido', async () => {
  const inicio = Date.now();
  const promessa = aguardar(8);
  assert.ok(promessa instanceof Promise);
  await promessa;
  assert.ok(Date.now() - inicio >= 4, 'a espera deve durar pelo menos o tempo pedido');
});

test('conferirNome avisa pelos callbacks de sucesso e de erro', async () => {
  let ok = null;
  let erro = null;
  conferirNome('  Ana  ', (nome) => { ok = nome; }, (e) => { erro = e.message; });
  await new Promise((resolve) => setTimeout(resolve, 10));
  assert.equal(ok, 'Ana');
  assert.equal(erro, null);

  conferirNome('   ', (nome) => { ok = nome; }, (e) => { erro = e.message; });
  await new Promise((resolve) => setTimeout(resolve, 10));
  assert.equal(ok, 'Ana');
  assert.equal(erro, 'nome vazio');
});

test('proximoDaFila tira o primeiro da fila e valida a lista', () => {
  const fila = [{ senha: 'S001', nome: 'Ana' }, { senha: 'S002', nome: 'Bia' }];
  assert.deepEqual(proximoDaFila(fila), { senha: 'S001', nome: 'Ana' });
  assert.equal(fila.length, 1);
  assert.equal(fila[0].nome, 'Bia');
  assert.throws(() => proximoDaFila([]), /fila vazia/);
  assert.throws(() => proximoDaFila(null), /fila inválida/);
});

test('montarSenha formata o número com 3 casas', () => {
  assert.equal(montarSenha(5), 'S005');
  assert.equal(montarSenha(1), 'S001');
  assert.equal(montarSenha(123), 'S123');
});

test('emitirSenha junta callback, promise e montarSenha; rejeita nome vazio', async () => {
  const paciente = await emitirSenha('  Carla  ', 7);
  assert.deepEqual(paciente, { senha: 'S007', nome: 'Carla' });
  await assert.rejects(() => emitirSenha('   ', 3), /nome vazio/);
});

test('atenderProximo espera e atende o próximo; fila vazia rejeita', async () => {
  const fila = [{ senha: 'S001', nome: 'Ana' }, { senha: 'S002', nome: 'Bia' }];
  const atendido = await atenderProximo(fila);
  assert.deepEqual(atendido, { senha: 'S001', nome: 'Ana' });
  assert.equal(fila.length, 1);
  await assert.rejects(() => atenderProximo([]), /fila vazia/);
});
